                <button onClick={() => setActiveTab('messages')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all relative ${activeTab === 'messages' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconMail className="w-5 h-5" /><span className="font-medium">{t.messages}</span>{unreadMessagesCount > 0 && <span className="absolute rtl:left-4 ltr:right-4 bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{unreadMessagesCount}</span>}</button>
                <button onClick={() => setActiveTab('enterprise_sales')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'enterprise_sales' ? 'bg-orange-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconBriefcase className="w-5 h-5" /><span className="font-medium">{t.enterprise_sales}</span></button>
                <button onClick={() => setActiveTab('projects')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'projects' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconProject className="w-5 h-5" /><span className="font-medium">{t.projects}</span></button>
                <button onClick={() => setActiveTab('sales')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'sales' ? 'bg-green-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconMoney className="w-5 h-5" /><span className="font-medium">{t.sales}</span></button>
                {isAdmin && (<><div className="px-4 py-2 text-xs font-bold text-gray-400 mt-4 border-t border-gray-100 pt-4">Admin</div><button onClick={() => setActiveTab('personnel')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconShield className="w-5 h-5" /><span className="font-medium">{t.personnel}</span></button><button onClick={() => setActiveTab('settings')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconSettings className="w-5 h-5" /><span className="font-medium">{t.settings}</span></button></>)}
            </div>
            <button onClick={onLogout} className="w-full text-sm font-medium text-red-600 bg-red-50 hover:bg-red-100 py-3 rounded-xl transition-colors mt-6">{t.logout}</button>
        </div>
      </div>

      <div className="flex-grow">
        {activeTab === 'overview' && (
            <div className="space-y-8 animate-fade-in">
                 <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.myTasks}</div><div className="text-2xl font-black text-indigo-600">{myTasksCount}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.allRequests}</div><div className="text-2xl font-black text-gray-800">{tickets.filter(t => t.status !== 'تکمیل شده' && t.status !== 'لغو شده').length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.activeProjects}</div><div className="text-2xl font-black text-purple-600">{activeProjectsList.length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.newMessages}</div><div className="text-2xl font-black text-blue-600">{unreadMessagesCount}</div></div>
                 </div>
            </div>
        )}
        {activeTab === 'enterprise_sales' && <EnterpriseSalesManager currentUser={currentUser} lang={lang} />}
        {activeTab === 'projects' && (
            <div className="space-y-6 animate-fade-in">
                <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                    <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                        <div className="bg-purple-100 text-purple-600 p-2 rounded-lg"><IconProject className="w-6 h-6" /></div>
                        {t.projectDashboard}
                    </h2>
                </div>
            </div>
        )}
        {activeTab === 'sales' && <SalesDashboard currentUser={currentUser} personnel={personnel} services={services} onUpdatePersonnel={onUpdatePersonnel} onUpdateServices={onUpdateServices} lang={lang} />}
        {activeTab === 'messages' && <InternalMessenger currentUser={currentUser} personnel={personnel} messages={messages} lang={lang} />}
        {activeTab === 'tasks' && <TaskManager currentUser={currentUser} personnel={personnel} tasks={tasks} lang={lang} />}
        {activeTab === 'meetings' && <MeetingCalendar meetings={meetings} currentUser={currentUser} personnel={personnel} lang={lang} />}
        {activeTab === 'customers' && hasCustomerAccess && <CustomerManager customers={customers} currentUser={currentUser} onUpdate={onUpdateCustomers} onEdit={onEditCustomer} onDelete={onDeleteCustomer} lang={lang} />}
        {activeTab === 'services' && hasTariffAccess && <ServiceManager services={services} onUpdate={onUpdateServices} readonly={!isAdmin && !isMaster} lang={lang} />}
        {activeTab === 'personnel' && isAdmin && <PersonnelManager personnel={personnel} config={config} onUpdate={onUpdatePersonnel} onUpdateConfig={onUpdateConfig} lang={lang} />}
        {activeTab === 'settings' && isAdmin && <SettingsManager config={config} onUpdate={onUpdateConfig} isMaster={isMaster} />}
        {activeTab === 'reports' && isMaster && <PerformanceReports personnel={personnel} tickets={tickets} tasks={tasks} lang={lang} />}
        {activeTab === 'kpi' && isMaster && <KPIManager kpis={kpis} personnel={personnel} lang={lang} />}
        {activeTab === 'financial' && (isAdmin || isMaster) && renderFinancialReport()}
      </div>
      {selectedTicket && renderTicketModal()}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { EnterprisePartner, EnterpriseSale, Personnel, Currency } from '../types';
import { IconBriefcase, IconPlus, IconMoney, IconChart, IconUsers, IconTrash, IconEdit, IconCheck, IconFileText, IconCalendar, IconTrendingUp } from './Icons';
import { saveEnterprisePartner, subscribeToEnterprisePartners, deleteEnterprisePartner, saveEnterpriseSale, subscribeToEnterpriseSales, deleteEnterpriseSale } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  lang: Language;
}

export const EnterpriseSalesManager: React.FC<Props> = ({ currentUser, lang }) => {
  const [activeTab, setActiveTab] = useState<'partners' | 'sales' | 'reports'>('sales');
  const [partners, setPartners] = useState<EnterprisePartner[]>([]);
  const [sales, setSales] = useState<EnterpriseSale[]>([]);

  // Modals
  const [showPartnerModal, setShowPartnerModal] = useState(false);
  const [showSaleModal, setShowSaleModal] = useState(false);

  // Reporting Filters
  const [reportPartnerId, setReportPartnerId] = useState('all');
  const [reportMonth, setReportMonth] = useState(new Date().toISOString().slice(0, 7));

  // Form States
  const [newPartner, setNewPartner] = useState({ name: '', commRate: 10, contact: '', phone: '' });
  const [newSale, setNewSale] = useState({ partnerId: '', productName: '', customerName: '', totalAmount: '', commPercent: 0, date: new Date().toISOString().split('T')[0], notes: '' });

  useEffect(() => {
    const unsubPartners = subscribeToEnterprisePartners(setPartners);
    const unsubSales = subscribeToEnterpriseSales(setSales);
    return () => { unsubPartners(); unsubSales(); };
  }, []);

  const t = {
    fa: {
      partners: 'لیست شرکت‌های طرف قرارداد',
      sales: 'ثبت و پایش فروش کالا',
      reports: 'گزارش‌دهی به تفکیک شرکت',
      addPartner: 'افزودن شرکت همکار',
      addSale: 'ثبت فروش کالای جدید',
      partnerName: 'نام شرکت / برند',
      defaultComm: 'درصد کارمزد پیش‌فرض ما (%)',
      contact: 'شخص رابط',
      phone: 'تلفن تماس',
      productName: 'نام کالا / محموله',
      customerName: 'مشتری نهایی (خریدار)',
      totalAmount: 'مبلغ کل فروش',
      commPercent: 'درصد سهم ما از این فروش',
      ourProfit: 'سود ناخالص ما (کارمزد)',
      date: 'تاریخ فروش',
      notes: 'توضیحات تکمیلی',
      save: 'ذخیره',
      cancel: 'انصراف',
      empty: 'موردی یافت نشد.',
      totalSales: 'فروش کل دوره‌ای',
      totalOurComm: 'مجموع کارمزد دریافتی ما',
      filterPartner: 'فیلتر بر اساس شرکت',
      month: 'بازه زمانی (ماه)'
    },
    en: {
      partners: 'Enterprise Partners',
      sales: 'Product Sales Log',
      reports: 'Enterprise Reports',
      addPartner: 'Add New Partner',
      addSale: 'Record New Sale',
      partnerName: 'Partner Name',
      defaultComm: 'Our Default Comm. (%)',
      contact: 'Contact Person',
      phone: 'Phone',
      productName: 'Product / Shipment',
      customerName: 'Final Customer',
      totalAmount: 'Total Sale Amount',
      commPercent: 'Our Comm. % for this sale',
      ourProfit: 'Our Gross Profit',
      date: 'Sale Date',
      notes: 'Notes',
      save: 'Save',
      cancel: 'Cancel',
      empty: 'No records found.',
      totalSales: 'Total Periodic Sales',
      totalOurComm: 'Total Our Commission',
      filterPartner: 'Filter by Partner',
      month: 'Period (Month)'
    }
  }[lang];

  const handlePartnerSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const p: EnterprisePartner = {
      id: `ep-${Date.now()}`,
      name: newPartner.name,
      defaultCommissionRate: Number(newPartner.commRate),
      contactPerson: newPartner.contact,
      phoneNumber: newPartner.phone,
      createdAt: new Date().toISOString()
    };
    await saveEnterprisePartner(p);
    setShowPartnerModal(false);
    setNewPartner({ name: '', commRate: 10, contact: '', phone: '' });
  };

  const handleSaleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const partner = partners.find(p => p.id === newSale.partnerId);
    if (!partner) return;

    const amount = Number(newSale.totalAmount.replace(/,/g, ''));
    const profit = (amount * Number(newSale.commPercent)) / 100;

    const s: EnterpriseSale = {
      id: `es-${Date.now()}`,
      partnerId: partner.id,
      partnerName: partner.name,
      productName: newSale.productName,
      customerName: newSale.customerName,
      totalAmount: amount,
      currency: 'IRR',
      ourCommissionPercent: Number(newSale.commPercent),
      ourCommissionAmount: profit,
      date: newSale.date,
      notes: newSale.notes,
      createdAt: new Date().toISOString()
    };
    await saveEnterpriseSale(s);
    setShowSaleModal(false);
    setNewSale({ partnerId: '', productName: '', customerName: '', totalAmount: '', commPercent: 0, date: new Date().toISOString().split('T')[0], notes: '' });
  };

  const filteredSales = useMemo(() => {
    return sales.filter(s => {
      const matchPartner = reportPartnerId === 'all' || s.partnerId === reportPartnerId;
      const matchMonth = !reportMonth || s.date.startsWith(reportMonth);
      return matchPartner && matchMonth;
    });
  }, [sales, reportPartnerId, reportMonth]);

  const reportStats = useMemo(() => {
    const total = filteredSales.reduce((acc, s) => acc + s.totalAmount, 0);
    const profit = filteredSales.reduce((acc, s) => acc + s.ourCommissionAmount, 0);
    return { total, profit };
  }, [filteredSales]);

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header & Tabs */}
      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <div className="bg-orange-100 text-orange-600 p-2 rounded-lg"><IconBriefcase className="w-6 h-6" /></div>
            سیستم فروش اختصاصی شرکت‌ها
          </h2>
        </div>
        <div className="flex bg-gray-100 p-1 rounded-xl">
          <button onClick={() => setActiveTab('sales')} className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'sales' ? 'bg-white shadow text-orange-600' : 'text-gray-500'}`}>{t.sales}</button>
          <button onClick={() => setActiveTab('partners')} className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'partners' ? 'bg-white shadow text-orange-600' : 'text-gray-500'}`}>{t.partners}</button>
          <button onClick={() => setActiveTab('reports')} className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'reports' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.reports}</button>
        </div>
      </div>

      {/* Sales Log Tab */}
      {activeTab === 'sales' && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <button onClick={() => setShowSaleModal(true)} className="bg-orange-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-orange-700 shadow-lg shadow-orange-100 flex items-center gap-2">
              <IconPlus className="w-5 h-5" /> {t.addSale}
            </button>
          </div>
          <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden shadow-sm">
            <table className="w-full text-right text-sm">
              <thead className="bg-gray-50 text-gray-500 font-bold">
                <tr>
                  <th className="px-6 py-4">تاریخ</th>
                  <th className="px-6 py-4">شرکت (تأمین‌کننده)</th>
                  <th className="px-6 py-4">کالا / محموله</th>
                  <th className="px-6 py-4">مبلغ کل</th>
                  <th className="px-6 py-4">سهم ما (کارمزد)</th>
                  <th className="px-6 py-4 text-center">عملیات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {sales.map(sale => (
                  <tr key={sale.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4 font-mono text-xs text-gray-400">{sale.date}</td>
                    <td className="px-6 py-4 font-bold text-gray-800">{sale.partnerName}</td>
                    <td className="px-6 py-4 text-gray-600">{sale.productName}</td>
                    <td className="px-6 py-4 font-bold">{sale.totalAmount.toLocaleString()}</td>
                    <td className="px-6 py-4 text-green-600 font-black">
                      {sale.ourCommissionAmount.toLocaleString()} 
                      <span className="text-[10px] text-gray-400 mr-1">({sale.ourCommissionPercent}%)</span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <button onClick={() => deleteEnterpriseSale(sale.id)} className="text-red-300 hover:text-red-500 p-1"><IconTrash className="w-4 h-4" /></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {sales.length === 0 && <div className="py-20 text-center text-gray-400">{t.empty}</div>}
          </div>
        </div>
      )}

      {/* Partners Tab */}
      {activeTab === 'partners' && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <button onClick={() => setShowPartnerModal(true)} className="bg-orange-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-orange-700 shadow-lg shadow-orange-100 flex items-center gap-2">
              <IconPlus className="w-5 h-5" /> {t.addPartner}
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {partners.map(p => (
              <div key={p.id} className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm hover:shadow-md transition-all group">
                <div className="flex justify-between items-start mb-4">
                   <div className="w-12 h-12 bg-orange-50 rounded-xl flex items-center justify-center text-orange-600 font-black text-xl">{p.name.charAt(0)}</div>
                   <button onClick={() => deleteEnterprisePartner(p.id)} className="opacity-0 group-hover:opacity-100 text-red-300 hover:text-red-500 transition-opacity"><IconTrash className="w-4 h-4" /></button>
                </div>
                <h3 className="font-bold text-gray-900 text-lg mb-1">{p.name}</h3>
                <div className="text-xs text-gray-500 mb-4">{p.contactPerson} - {p.phoneNumber}</div>
                <div className="pt-4 border-t border-gray-50 flex justify-between items-center">
                  <span className="text-xs text-gray-400">کارمزد ثابت ما:</span>
                  <span className="bg-orange-100 text-orange-700 px-3 py-1 rounded-full font-black text-sm">{p.defaultCommissionRate}%</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Reports Tab */}
      {activeTab === 'reports' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
            <div>
              <label className="block text-xs font-bold text-gray-500 mb-2">{t.filterPartner}</label>
              <select className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 outline-none" value={reportPartnerId} onChange={e => setReportPartnerId(e.target.value)}>
                <option value="all">همه شرکت‌ها</option>
                {partners.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-500 mb-2">{t.month}</label>
              <input type="month" className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 outline-none" value={reportMonth} onChange={e => setReportMonth(e.target.value)} />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-indigo-600 p-8 rounded-3xl text-white shadow-xl shadow-indigo-100">
               <div className="text-indigo-200 text-sm font-bold mb-2">{t.totalSales}</div>
               <div className="text-4xl font-black">{reportStats.total.toLocaleString()} <span className="text-xl font-normal opacity-50">ریال</span></div>
            </div>
            <div className="bg-emerald-600 p-8 rounded-3xl text-white shadow-xl shadow-emerald-100">
               <div className="text-emerald-200 text-sm font-bold mb-2">{t.totalOurComm}</div>
               <div className="text-4xl font-black">{reportStats.profit.toLocaleString()} <span className="text-xl font-normal opacity-50">ریال</span></div>
            </div>
          </div>

          <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden">
             <table className="w-full text-right text-sm">
               <thead className="bg-gray-50 font-bold">
                 <tr>
                   <th className="px-6 py-4">شرح</th>
                   <th className="px-6 py-4">مبلغ فروش</th>
                   <th className="px-6 py-4">سهم شرکت ما</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-gray-100">
                 {filteredSales.map(s => (
                   <tr key={s.id}>
                     <td className="px-6 py-4">
                       <div className="font-bold text-gray-800">{s.productName}</div>
                       <div className="text-[10px] text-gray-400">{s.partnerName}</div>
                     </td>
                     <td className="px-6 py-4 font-mono">{s.totalAmount.toLocaleString()}</td>
                     <td className="px-6 py-4 text-emerald-600 font-black">{s.ourCommissionAmount.toLocaleString()}</td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        </div>
      )}

      {/* Sale Modal */}
      {showSaleModal && (
        <div className="fixed inset-0 z-[130] bg-black/60 flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-8 shadow-2xl animate-fade-in">
            <h3 className="text-xl font-black mb-6 text-orange-900 border-b pb-4">{t.addSale}</h3>
            <form onSubmit={handleSaleSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-400 mb-1 uppercase">{t.partnerName}</label>
                <select className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 outline-none focus:border-orange-500" required value={newSale.partnerId} onChange={e => {
                  const partner = partners.find(p => p.id === e.target.value);
                  setNewSale({...newSale, partnerId: e.target.value, commPercent: partner?.defaultCommissionRate || 0});
                }}>
                  <option value="">انتخاب شرکت...</option>
                  {partners.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 mb-1 uppercase">{t.productName}</label>
                <input className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 outline-none focus:border-orange-500" required value={newSale.productName} onChange={e => setNewSale({...newSale, productName: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase">{t.totalAmount}</label>
                  <input className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 outline-none focus:border-orange-500 dir-ltr text-right" required value={newSale.totalAmount} onChange={e => setNewSale({...newSale, totalAmount: e.target.value.replace(/\D/g, "").replace(/\B(?=(\d{3})+(?!\d))/g, ",")})} />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase">{t.commPercent}</label>
                  <input type="number" className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 outline-none focus:border-orange-500" required value={newSale.commPercent} onChange={e => setNewSale({...newSale, commPercent: Number(e.target.value)})} />
                </div>
              </div>
              <div className="flex justify-between items-center p-4 bg-orange-50 rounded-2xl border border-orange-100">
                <span className="text-xs font-bold text-orange-800">{t.ourProfit}</span>
                <span className="font-black text-orange-900">
                  {((Number(newSale.totalAmount.replace(/,/g, '')) || 0) * (newSale.commPercent || 0) / 100).toLocaleString()} ریال
                </span>
              </div>
              <div className="flex gap-2 pt-4">
                <button type="button" onClick={() => setShowSaleModal(false)} className="flex-1 py-3 text-gray-500 font-bold hover:bg-gray-50 rounded-xl transition-all">{t.cancel}</button>
                <button type="submit" className="flex-1 py-3 bg-orange-600 text-white font-black rounded-xl shadow-lg shadow-orange-100 hover:bg-orange-700 transition-all">{t.save}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Partner Modal */}
      {showPartnerModal && (
